Input: {"question": "When was the PMK founded?", "original_source_segments": {"D1S1": {"document_number": 1, "doc_id": "ramdocs-0154-ba33f5bcc625:d00", "start": 0, "end": 142, "text": "Pattali Makkal Katchi Paattali Makkal Katchi (English: abbreviated in English as PMK) is a political party in Tamil Nadu, India, founded by S."}, "D1S2": {"document_number": 1, "doc_id": "ramdocs-0154-ba33f5bcc625:d00", "start": 143, "end": 198, "text": "Ramadoss in 1989 for the upliftment of Tamil community."}, "D1S3": {"document_number": 1, "doc_id": "ramdocs-0154-ba33f5bcc625:d00", "start": 199, "end": 220, "text": "PMK was founded by S."}, "D1S4": {"document_number": 1, "doc_id": "ramdocs-0154-ba33f5bcc625:d00", "start": 221, "end": 260, "text": "Ramadoss, an activist, on 16 July 1989."}, "D1S5": {"document_number": 1, "doc_id": "ramdocs-0154-ba33f5bcc625:d00", "start": 261, "end": 549, "text": "Ahead of the 2004 elections, PMK joined the Democratic Progressive Alliance, a broad Tamil political front which also included the Dravida Munnetra Kazhagam (DMK), Indian National Congress (INC), Communist Party of India, Communist Party of India (Marxist) and Indian Union Muslim League."}, "D1S6": {"document_number": 1, "doc_id": "ramdocs-0154-ba33f5bcc625:d00", "start": 550, "end": 622, "text": "PMK was able to obtain a significant share of power both in the regional"}, "D2S1": {"document_number": 2, "doc_id": "ramdocs-0154-ba33f5bcc625:d01", "start": 0, "end": 212, "text": "People's Movement of Kosovo The People's Movement of Kosovo () was a political party in Kosovo active after the Kosovo War, having originally been founded as a political movement of Albanian nationalists in 1981."}, "D2S2": {"document_number": 2, "doc_id": "ramdocs-0154-ba33f5bcc625:d01", "start": 213, "end": 345, "text": "Despite participating in several elections in autonomous Kosovo, its pre-war existence was its most historically significant period."}, "D2S3": {"document_number": 2, "doc_id": "ramdocs-0154-ba33f5bcc625:d01", "start": 346, "end": 509, "text": "Historically, its support and membership came from Albanian diaspora, especially within Switzerland and Germany, originating mainly from former Yugoslav republics."}, "D2S4": {"document_number": 2, "doc_id": "ramdocs-0154-ba33f5bcc625:d01", "start": 510, "end": 643, "text": "The LPK was formed in the early 1980s, during the turmoil which would bring the Albanian population of Yugoslavia to wider attention."}, "D2S5": {"document_number": 2, "doc_id": "ramdocs-0154-ba33f5bcc625:d01", "start": 644, "end": 690, "text": "During the 1981 protests in Kosovo, protesters"}, "D3S1": {"document_number": 3, "doc_id": "ramdocs-0154-ba33f5bcc625:d02", "start": 0, "end": 438, "text": "Marxism–Leninism Hoxhaism [ 1 ] After October 1990 : Self-determination Social conservatism Liberal conservatism [ 2 ] Political position Far-left ( 1982-1990 ) Centre-right ( 1990-1999 ) Colours Red , Black and Yellow Politics of Kosovo Political parties Elections Close Ideology Summarize Perspective The LPK was formed in the early 1980s , during the turmoil which would bring the Albanian population of Yugoslavia to wider attention ."}, "D3S2": {"document_number": 3, "doc_id": "ramdocs-0154-ba33f5bcc625:d02", "start": 439, "end": 579, "text": "During the 1981 protests in Kosovo , protesters demanded that Kosovo become a republic within the Socialist Federal Republic of Yugoslavia ."}, "D3S3": {"document_number": 3, "doc_id": "ramdocs-0154-ba33f5bcc625:d02", "start": 580, "end": 640, "text": "[ 3 ] The movement was crystallized [ clarification needed ]"}, "D4S1": {"document_number": 4, "doc_id": "ramdocs-0154-ba33f5bcc625:d03", "start": 0, "end": 8, "text": "proven ."}, "D4S2": {"document_number": 4, "doc_id": "ramdocs-0154-ba33f5bcc625:d03", "start": 9, "end": 207, "text": "Therefore , until arguments of Paleolithic and Mesolithic man are confirmed , Neolithic man , respectively the Neolithic sites are considered as the chronological beginning of population in Kosovo ."}, "D4S3": {"document_number": 4, "doc_id": "ramdocs-0154-ba33f5bcc625:d03", "start": 208, "end": 516, "text": "From this period until today Kosovo has been inhabited , and traces of activities of societies from prehistoric , ancient and up to mediaeval time are visible throughout its territory , whereas , in some archaeological sites , multilayer settlements clearly reflect the continuity of life through centuries ."}, "D4S4": {"document_number": 4, "doc_id": "ramdocs-0154-ba33f5bcc625:d03", "start": 517, "end": 615, "text": "[ 5 ] Vlashnjë and Runik are two of the most significant Neolithic sites which have been found and"}, "D5S1": {"document_number": 5, "doc_id": "ramdocs-0154-ba33f5bcc625:d04", "start": 0, "end": 265, "text": "ADR undertakes great care and adopts utmost due diligence in analysing and dissemination of the background information of the candidates furnished by them at the time of elections from the duly self-sworn affidavits submitted with the Election Commission of India ."}, "D5S2": {"document_number": 5, "doc_id": "ramdocs-0154-ba33f5bcc625:d04", "start": 266, "end": 521, "text": "Such information is only aimed at highlighting the growing criminality in politics , increased misuse of money in elections so as to facilitate a system of transparency , accountability and good governance and to enable voters to form an informed choice ."}, "D5S3": {"document_number": 5, "doc_id": "ramdocs-0154-ba33f5bcc625:d04", "start": 522, "end": 625, "text": "Therefore , it is expected that anyone using this report shall undertake due care and utmost precaution"}}, "original_cards": [{"doc_id": "ramdocs-0154-ba33f5bcc625:d00", "card_id": "ramdocs-0154-ba33f5bcc625:d00:c0", "entity": "PMK", "scope": "founding date", "claim": "PMK was founded on 16 July 1989.", "answer": "16 July 1989", "quote": "Ramadoss, an activist, on 16 July 1989.", "original_document_number": 1}, {"doc_id": "ramdocs-0154-ba33f5bcc625:d01", "card_id": "ramdocs-0154-ba33f5bcc625:d01:c0", "entity": "People's Movement of Kosovo", "scope": "founding year", "claim": "The People's Movement of Kosovo was originally founded as a political movement of Albanian nationalists in 1981.", "answer": "1981", "quote": "People's Movement of Kosovo The People's Movement of Kosovo () was a political party in Kosovo active after the Kosovo War, having originally been founded as a political movement of Albanian nationalists in 1981.", "original_document_number": 2}], "current_answers": ["16 July 1989", "1981"], "candidate_answers": [{"candidate_id": "R0", "answer": "16 July 1989", "origin": "initial"}, {"candidate_id": "R1", "answer": "1981", "origin": "initial"}]}

